        float linear_to_srgb(float channel) {
            if(channel <= 0.0031308)
                return 12.92 * channel;
            else
                return (1.0 + amzp_SRGB_ALPHA) * pow(channel, 1.0/amzp_SRGB_GAMMA) - amzp_SRGB_ALPHA;
        }
